<style>
    .orion-salary-inner,.orion-salary-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}.orion-salary-inner{--osi-panel:#0c1728;--osi-panel2:#0f1b2e;--osi-border:#21324d;--osi-soft:#17263c;--osi-text:#eef3fb;--osi-muted:#71839e;--osi-purple:#8b5cf6;--osi-green:#34d399;--osi-red:#fb7185;--osi-amber:#fbbf24;--osi-blue:#60a5fa;direction:rtl;color:var(--osi-text);width:100%;padding-bottom:24px}.fi-header{margin-bottom:14px!important}.fi-header-heading{color:#f3f6fb!important;font-weight:950!important}.fi-breadcrumbs{color:#697b96!important}.osi-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:120px;padding:18px 19px;margin-bottom:13px;border:1px solid var(--osi-border);border-radius:15px;background:radial-gradient(circle at 7% 5%,rgba(139,92,246,.18),transparent 30%),radial-gradient(circle at 92% 110%,rgba(96,165,250,.07),transparent 32%),linear-gradient(145deg,#0e192b,#0a1423);box-shadow:0 18px 45px rgba(0,0,0,.12)}.osi-hero-main{display:flex;align-items:center;gap:13px;min-width:0}.osi-icon,.osi-avatar{width:52px;height:52px;border-radius:15px;flex:none;display:grid;place-items:center;border:1px solid rgba(139,92,246,.42);background:linear-gradient(145deg,rgba(124,58,237,.32),rgba(45,27,91,.2));box-shadow:0 12px 30px rgba(76,29,149,.18);color:#d2c8ff}.osi-avatar{font-size:19px;font-weight:950}.osi-icon svg{width:24px;height:24px}.osi-eyebrow{color:#8e7be8;font-size:8px;font-weight:950;letter-spacing:1.35px;margin-bottom:4px}.osi-title{color:#f5f7fb;font-size:18px;font-weight:950;line-height:1.25}.osi-sub{color:var(--osi-muted);font-size:9px;font-weight:650;margin-top:5px}.osi-chips{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.osi-chip{display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border:1px solid #263a58;border-radius:9px;background:#0c1829;color:#9aabc0;font-size:8px;font-weight:900;white-space:nowrap}.osi-chip strong{color:#e4eaf3;font-size:9px;direction:ltr}.osi-chip.green{border-color:rgba(52,211,153,.23);background:rgba(52,211,153,.055);color:#6eddb8}.osi-chip.amber{border-color:rgba(251,191,36,.22);background:rgba(251,191,36,.05);color:#f1c85e}.osi-chip.blue{border-color:rgba(96,165,250,.22);background:rgba(96,165,250,.05);color:#79b6ff}.osi-chip.red{border-color:rgba(251,113,133,.22);background:rgba(251,113,133,.05);color:#ff8798}.osi-dot{width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 9px currentColor}.osi-content .fi-section{overflow:hidden!important;border:1px solid var(--osi-border)!important;border-radius:14px!important;background:linear-gradient(145deg,#0c1728,#091421)!important;box-shadow:none!important}.osi-content .fi-section+.fi-section{margin-top:11px!important}.osi-content .fi-section-header{border-bottom:1px solid var(--osi-soft)!important;background:rgba(255,255,255,.012)!important}.osi-content .fi-section-header-heading{color:#e8edf5!important;font-weight:950!important}.osi-content .fi-section-header-description{color:#657792!important;font-size:10px!important}.osi-content .fi-input-wrp,.osi-content .fi-select-input{border-color:#263a59!important;background:#0d192b!important;box-shadow:none!important}.osi-content .fi-input,.osi-content textarea{color:#e1e8f2!important}.osi-content .fi-fo-field-wrp-label{color:#9aa9bd!important;font-weight:800!important}.osi-content .fi-fo-field-wrp-helper-text{color:#596c87!important}.osi-content .fi-ac-btn-action{border-radius:9px!important}@media(max-width:850px){.osi-hero{align-items:flex-start;flex-direction:column}.osi-chips{justify-content:flex-start}}
</style>
